let now=0;function step(n=1){for(let i=0;i<n;i++){now+=16.67;if(win.__t&&win.__t.audio)win.__t.audio.currentTime+=1/60;const cb=rafCb;rafCb=null;cb(now);if(!rafCb)throw new Error('frame did not re-register');}}
let passed=0,failed=0;const fails=[];
const TESTS=[];function check(name,fn){TESTS.push([name,fn]);}
async function runChecks(){for(const [name,fn] of TESTS){try{await fn();passed++;console.log('  ok   '+name);}catch(e){failed++;fails.push(name+': '+(e&&e.stack||e));console.log('  FAIL '+name+' -> '+(e&&e.message||e));}}}
function assert(c,msg){if(!c)throw new Error(msg||'assertion failed');}
// ---- tests ----
if(require.main!==module){module.exports={boot,step,byId,doc,store,check,assert};return;}
console.log('Booting game script...');
let t=boot();
const stick=(color='#e65345')=>t.botStrokes(color).map(s=>({...s,points:s.points.map(p=>({...p}))}));
check('boots and renders 5 frames',()=>{step(5);assert(t.game===null);});
check('rig inferred from a stick figure and Walk animates',()=>{t.setStrokes(stick());assert(t.startAnimation('Walk'));assert(t.rig,'rig missing');assert(t.rig.fit.scale>0);step(40);assert(t.animation==='Walk');t.stopAnimation();});
check('every movement animates',()=>{for(const m of ['Walk','Run','Jump','Dance','Wave','Kick','Flip','Cartwheel','Fly','Zombie']){assert(t.startAnimation(m));step(10);t.stopAnimation();}});
check('fight poses resolve for every fit',()=>{for(const n of ['Guard','Punch','Swing','Shoot','Block','Hurt','KO','Win','Fall','Sit']){const p=t.poseFor(n,.3,t.rig.fit);assert(p&&typeof p==='object');for(const k in p)assert(Number.isFinite(p[k]),n+'.'+k+' not finite');}});
check('outfits and morph paint without errors',()=>{for(const hat of ['','crown','wizard','cap','helmet','halo','party','horns'])for(const weapon of ['','sword','axe','hammer','wand','blaster','bow','shield']){t.setOutfit({hat,cape:['','red','rainbow','shadow'][hat.length%4],top:['','shirt','armor','super','robe','ninja','stripes'][weapon.length%7],weapon});t.startAnimation('Run');step(3);t.stopAnimation();}t.setMorph(true);step(80);assert(t.morphT===1,'morphT '+t.morphT);t.startAnimation('Dance');step(20);t.stopAnimation();t.setMorph(false);step(80);assert(t.morphT===0);});
check('all 18 scenes draw (normal and thumbnails)',()=>{for(let i=0;i<t.SCENES.length;i++){t.setBackground(i);t.scene(1.5,300);}t.openScenePicker();t.closeModal();t.setBackground(6);});
check('legacy games run with outfits on',()=>{t.setOutfit({hat:'crown',cape:'red',top:'super',weapon:'sword'});t.setMorph(true);for(const type of ['platform','dash','catch','flap','pop','dodge','bounce','goal']){assert(t.startGame(type),type);for(let i=0;i<240;i++){if(i%40===0)t.held.right.add('k');if(i%40===25)t.held.right.delete('k');if(i%30===0)t.jump();step(1);}t.backToDrawing();}});
check('hero library: save, build, thumbnail, load',()=>{const h=t.snapshotHero('Test Hero');assert(h&&h.name==='Test Hero');assert(t.heroes.length===1);const ch=t.buildCharacter(h);assert(ch.rig.bindings.size===h.strokes.length);const c=doc.createElement('canvas');c.width=c.height=140;t.drawCharacterThumb(c,ch);t.loadHero(h);assert(t.rig&&t.heroName==='Test Hero');t.openHeroes();t.closeModal();});
check('all four bots build',()=>{for(const b of t.BOTS){const ch=t.makeBot(b);assert(ch.rig.fit.headR>10,b.name+' head');assert(ch.rest.h>200,b.name+' height');}});
check('online hero payload round-trips',()=>{const me=t.currentCharacter();const s=JSON.parse(JSON.stringify(t.serializeChar(me)));assert(t.validChar(s));const back=t.buildCharacter(s);assert(back.strokes.length===s.strokes.length);});
function randomInputs(pl,i){const acts=['left','right','up','a','b','c'];if(i%7===0){for(const a of acts)t.inputUp(pl,a,'t');t.inputDown(pl,acts[(i/7|0)%acts.length],'t');}}
check('VS Computer fight finishes with a result (hard bot, weapons)',()=>{const me=t.currentCharacter();const bot=t.makeBot(t.BOTS[0]);assert(t.startModGame(t.FIGHT,{p1:me,p2:bot,cpu:'hard'}));let i=0;while(!t.game.over&&i<60*200){randomInputs('p1',i);step(1);i++;}assert(t.game.over,'fight never ended');assert(byId.get('resultTitle').textContent.length>0);t.backToDrawing();});
check('2-player fight, all bots, finishes',()=>{const a=t.makeBot(t.BOTS[1]),b=t.makeBot(t.BOTS[3]);assert(t.startModGame(t.FIGHT,{p1:a,p2:b}));assert(t.game.duo===true);let i=0;while(!t.game.over&&i<60*200){randomInputs('p1',i);randomInputs('p2',i+3);step(1);i++;}assert(t.game.over,'2p fight never ended');t.backToDrawing();});
check('round timer runs out gives a decision',()=>{const a=t.makeBot(t.BOTS[2]),b=t.makeBot(t.BOTS[2]);t.startModGame(t.FIGHT,{p1:a,p2:b});let i=0;while(!t.game.over&&i<60*230){step(1);i++;}assert(t.game.over,'idle fight never ended');t.backToDrawing();});
check('Monster Brawl: a scripted player beats wave 1 slimes by punching',()=>{assert(t.startModGame(t.BRAWL,{}));let i=0;while(!t.game.over&&i<60*60){const A=t.game.arena,f=A.player,e=A.enemies[0];if(A.wave>=2)break;if(e){const d=e.x-f.x;t.inputUp('p1','left','k');t.inputUp('p1','right','k');if(Math.abs(d)>90)t.inputDown('p1',d>0?'right':'left','k');else if(i%20===0)t.inputDown('p1','a','k');else t.inputUp('p1','a','k');}step(1);i++;}assert(t.game.arena.kills>=3,'kills '+t.game.arena.kills+' hp '+t.game.arena.player.hp);t.backToDrawing();});
check('Monster Brawl: all waves and the boss can be won',()=>{assert(t.startModGame(t.BRAWL,{}));let i=0,waves=new Set();while(!t.game.over&&i<60*120){const A=t.game.arena;waves.add(A.wave);A.player.hp=100;if(i%60===0)A.enemies.forEach(e=>{e.hp=0;});step(1);i++;}assert(t.game.over&&/Champion/.test(byId.get('resultTitle').textContent),'waves '+[...waves]+' title '+byId.get('resultTitle').textContent);t.backToDrawing();});
check('Monster Brawl loss path',()=>{t.startModGame(t.BRAWL,{});t.game.arena.player.hp=1;let i=0;while(!t.game.over&&i<60*60){step(1);i++;}assert(t.game.over);assert(/wave/i.test(byId.get('resultText').textContent));t.backToDrawing();});
check('Space Quest: every world generates and runs',()=>{for(let w=0;w<t.WORLDS.length;w++){const L=t.genLevel(t.WORLDS[w]);assert(L.cells.length===5&&L.segs.length>0,'world '+w);assert(t.startModGame(t.QUEST,{world:w}));for(let i=0;i<400&&!t.game.over;i++){randomInputs('p1',i);step(1);}t.backToDrawing();}});
check('Space Quest: chain Earth to the Sun by reaching each rocket',()=>{t.progress.quest.unlocked=1;assert(t.startModGame(t.QUEST,{world:0}));let guard=0;while(!t.game.over&&guard<60*60*5){const q=t.game.q;if(q.phase==='play'){q.p.x=q.level.goal;q.p.y=640;}step(1);guard++;}assert(t.game.over,'never finished');assert(/Sun/.test(byId.get('resultTitle').textContent),byId.get('resultTitle').textContent);assert(t.progress.quest.unlocked===t.WORLDS.length,'unlocked '+t.progress.quest.unlocked);t.openQuestMap();t.closeModal();t.backToDrawing();});
check('Space Quest: falling into pits three times ends the level',()=>{t.startModGame(t.QUEST,{world:2});const q=t.game.q;q.level.segs=[];q.level.plats=[];let i=0;while(!t.game.over&&i<60*30){q.p.inv=0;step(1);i++;}assert(t.game.over,'hearts '+t.game.hearts);assert(/try/i.test(byId.get('resultTitle').textContent));t.backToDrawing();});
check('House Hunt: walk every room and find all 8 things',()=>{assert(t.startModGame(t.HOUSE,{}));const h=t.game.h;const visited=new Set();const go=(room,x)=>{h.room=room;h.p.x=x;};const items=[['living',600],['kitchen',560],['bedroom',520],['bathroom',380],['yard',1000],['garage',980],['basement',1000],['playroom',700]];for(const [room,x] of items){go(room,x);visited.add(room);step(2);}assert(t.game.over,'not finished, found '+h.found.size);assert(/found everything/i.test(byId.get('resultTitle').textContent));t.backToDrawing();
t.startModGame(t.HOUSE,{});const H2=t.game.h;H2.p.x=20;t.inputDown('p1','left','k');step(2);assert(H2.room==='garage','door left -> '+H2.room);t.inputUp('p1','left','k');H2.p.x=1270;t.inputDown('p1','right','k');step(3);assert(H2.room==='living','door right -> '+H2.room);t.inputUp('p1','right','k');H2.p.x=1090;t.inputDown('p1','up','k');step(1);t.inputUp('p1','up','k');assert(H2.room==='bedroom','stairs up -> '+H2.room);t.inputDown('p1','down','k');step(1);t.inputUp('p1','down','k');assert(H2.room==='living','stairs down -> '+H2.room);t.backToDrawing();});
check('save + reload keeps outfit, morph, heroes and progress',()=>{t.setOutfit({hat:'halo',cape:'gold',top:'ninja',weapon:'bow'});t.setMorph(true);t.storageSave();const saved=JSON.parse(store.get('doodle-go-v1'));assert(saved.outfit.hat==='halo'&&saved.morph===true);t=boot();step(2);assert(t.outfit.hat==='halo'&&t.outfit.weapon==='bow',JSON.stringify(t.outfit));assert(t.morph===true&&t.morphT===1);assert(t.heroes.length===1);assert(t.progress.quest.unlocked===t.WORLDS.length);assert(t.rig,'rig restored');});
check('VS setup modal builds with current drawing, heroes and bots',()=>{const opts=t.fightOptions();assert(opts.length===1+1+t.BOTS.length,'options '+opts.length);t.openVsSetup(true);t.closeModal();t.openVsSetup(false);t.closeModal();t.openOnline();t.closeModal();});
check('guest fight applies host snapshots',()=>{const me=t.currentCharacter(),bot=t.makeBot(t.BOTS[2]);t.startModGame(t.FIGHT,{p1:bot,p2:me,online:{role:'guest'}});t.NET.role='guest';t.NET.state={t:'st',ph:'fight',pt:1,rd:1,tm:50,f:[{x:400,y:640,vx:0,vy:0,fc:1,st:'punch',t:.1,hp:80,w:0,g:true,an:1},{x:700,y:640,vx:0,vy:0,fc:-1,st:'hurt',t:.1,hp:60,w:1,g:true,an:1}],sh:[{x:500,y:500,vx:600,type:'wand'}],ev:[{k:'hit',x:600,y:500}]};step(3);const A=t.game.arena;assert(A.fighters[0].hp===80&&A.fighters[1].hp===60&&A.phase==='fight');t.NET.role=null;t.backToDrawing();});
check('music: Elevator Groove schedules notes for a full loop after the first tap',()=>{t.unlockAudio();assert(t.audio,'no audio context');assert(t.MUSIC.running,'groove not running');const before=t.MUSIC.notes;for(let i=0;i<60*20;i++){step(1);t.musicTick();}assert(t.MUSIC.notes-before>400,'notes scheduled '+(t.MUSIC.notes-before));assert(t.MUSIC.step>=0&&t.MUSIC.step<t.GROOVE.bars*16);assert(Math.abs(t.noteHz('A4')-440)<1e-6&&Math.abs(t.noteHz('C#3')-138.59)<.01);t.musicPause();assert(!t.MUSIC.running);});
check('music: modes, song element, modal and persistence',()=>{t.openMusic();t.closeModal();t.setMusicMode('off');t.musicApply();assert(!t.MUSIC.running);t.songSet({name:'test.wav',type:'audio/wav',blob:{}});assert(t.MUSIC.songUrl==='blob:fake'&&t.MUSIC.songName==='test.wav');t.setMusicMode('song');t.musicApply();t.songPlay();t.openMusic();t.closeModal();t.storageSave();const saved=JSON.parse(store.get('doodle-go-v1'));assert(saved.musicMode==='song'&&saved.musicVol===1,JSON.stringify([saved.musicMode,saved.musicVol]));t=boot();step(2);assert(t.musicMode==='song','reloaded mode '+t.musicMode);assert(byId.get('music').textContent==='🎵 My song',byId.get('music').textContent);t.setMusicMode('groove');t.musicApply();assert(t.MUSIC.running,'groove restart');t.musicPause();});
check('Endless Dash: landing on an alien squishes it and scores (Mario stomp)',()=>{assert(t.startGame('dash'));const g=t.game;step(2);const e=g.enemies[0];assert(e,'no alien');g.x=e.x;g.y=e.y-120;g.vy=300;g.grounded=false;const stars=g.stars,hearts=g.hearts;let i=0;while(e.squish===undefined&&i<40){step(1);i++;}assert(e.squish!==undefined,'alien not squished after '+i+' frames (y '+g.y+')');assert(g.stars>=stars+1,'no star for the stomp');assert(g.hearts===hearts,'stomp cost a heart');assert(g.vy<0,'no bounce');step(50);assert(!g.enemies.includes(e),'squished alien still there');t.backToDrawing();});
check('Endless Dash: walking into an alien still hurts',()=>{assert(t.startGame('dash'));const g=t.game;step(2);const e=g.enemies[0];g.x=e.x-40;g.y=640;g.vy=0;g.invulnerable=0;const hearts=g.hearts;step(3);assert(g.hearts===hearts-1,'side hit did not hurt: '+g.hearts);assert(e.squish===undefined,'side hit squished it');t.backToDrawing();});
check('hat brim flip: saved, reloaded and kept on heroes',()=>{t.setOutfit({hat:'cap',cape:'',top:'',weapon:'axe',flip:true});t.startAnimation('Walk');step(3);t.stopAnimation();t.storageSave();const saved=JSON.parse(store.get('doodle-go-v1'));assert(saved.outfit.flip===true,'flip not saved');const h=t.snapshotHero('Brim Hero');assert(h.outfit.flip===true,'flip not on hero');t=boot();step(2);assert(t.outfit.flip===true&&t.outfit.hat==='cap','flip lost on reload '+JSON.stringify(t.outfit));assert(byId.get('brim').textContent.indexOf('left')>0,'brim button text '+byId.get('brim').textContent);t.setOutfit({hat:'crown',cape:'red',top:'super',weapon:'sword',flip:false});});
check('Monster Brawl: hero turns toward the nearest monster without pressing anything',()=>{assert(t.startModGame(t.BRAWL,{}));const A=t.game.arena,f=A.player;step(90);A.enemies.forEach(e=>{e.x=f.x+300;e.state='walk';e.speed=0;});step(2);assert(f.facing===1,'should face right, facing '+f.facing);A.enemies.forEach(e=>{e.x=f.x-300;});step(2);assert(f.facing===-1,'should face left, facing '+f.facing);t.backToDrawing();});
check('fighters: a punch tapped during hitstop is not lost',()=>{assert(t.startModGame(t.BRAWL,{}));const A=t.game.arena,f=A.player;step(90);A.enemies.forEach(e=>{e.x=f.x+400;e.speed=0;});A.hitstop=.2;t.inputDown('p1','a','k');step(1);t.inputUp('p1','a','k');step(1);assert(f.state!=='punch','punched during hitstop?');step(14);assert(f.state==='punch','buffered punch did not fire, state '+f.state+' buf '+JSON.stringify(f.buf));t.backToDrawing();});
check('Sky Pilot: fly through 15 rings, land, win',()=>{assert(t.startModGame(t.PLANE,{}));const g=t.game,F=g.f;let i=0;while(!g.over&&i<60*120){if(F.phase==='fly'){F.objs.length=0;const r=F.rings.find(r=>!r.done&&!r.miss&&r.x>F.dist+F.p.x-20);if(r){F.p.y=r.y;}if(i%50===0)t.inputDown('p1','a','k');else t.inputUp('p1','a','k');}step(1);i++;}assert(g.over&&/Ace/.test(byId.get('resultTitle').textContent),'title '+byId.get('resultTitle').textContent+' got '+F.got);assert(t.progress.bests.plane>=150,'best '+t.progress.bests.plane);t.backToDrawing();});
check('Sky Pilot: storms cost hearts and end the flight',()=>{assert(t.startModGame(t.PLANE,{}));const g=t.game,F=g.f;let i=0;while(!g.over&&i<60*60){F.p.inv=0;F.objs.length=0;F.objs.push({kind:'storm',x:F.dist+F.p.x,y:F.p.y,vx:0,vy:0,r:80,t0:0,dead:false});step(1);i++;}assert(g.over&&/Rough/.test(byId.get('resultTitle').textContent),'title '+byId.get('resultTitle').textContent);t.backToDrawing();});
check('Sky Pilot: random flying runs clean',()=>{assert(t.startModGame(t.PLANE,{}));for(let i=0;i<600&&!t.game.over;i++){randomInputs('p1',i);if(i%37===0)t.jump();step(1);}t.backToDrawing();});
check('Hoop Shot: a green-zone shot from the 3-point line scores 3',()=>{assert(t.startModGame(t.HOOPS,{}));const g=t.game,B=g.b;B.p.x=300;t.inputDown('p1','a','k');step(1);assert(B.charging,'not charging');B.charge=.55;t.inputUp('p1','a','k');step(1);assert(B.ball.st==='air','ball not shot: '+B.ball.st);let i=0;while(B.ball.st==='air'&&i<400){step(1);i++;}assert(B.score===3,'score '+B.score+' made '+B.made+' ball '+JSON.stringify(B.ball));step(150);assert(B.ball.st==='held','ball did not come back: '+B.ball.st);t.backToDrawing();});
check('Hoop Shot: close shot scores 2 and the buzzer ends the game',()=>{assert(t.startModGame(t.HOOPS,{}));const g=t.game,B=g.b;B.p.x=900;t.inputDown('p1','a','k');step(1);B.charge=.55;t.inputUp('p1','a','k');step(1);assert(B.ball.st==='air','not shot');let i=0;while(B.ball.st==='air'&&i<400){step(1);i++;}assert(B.score===2,'score '+B.score);B.timer=.1;step(10);assert(g.over&&/Buzzer/.test(byId.get('resultTitle').textContent),byId.get('resultTitle').textContent);assert(t.progress.bests.hoops===2,'best '+t.progress.bests.hoops);t.backToDrawing();});
check('Hoop Shot: a bad shot misses and random play runs clean',()=>{assert(t.startModGame(t.HOOPS,{}));const B=t.game.b;B.p.x=300;t.inputDown('p1','a','k');step(1);B.charge=0;B.meter=0;t.inputUp('p1','a','k');let i=0;while(B.ball.st==='air'&&i<400){step(1);i++;}assert(B.score===0,'weak shot scored');for(let j=0;j<500&&!t.game.over;j++){randomInputs('p1',j);step(1);}t.backToDrawing();});
check('upgrade pack: every hat, cape, top, weapon and skin paints, morphed and not',()=>{const all=k=>t.OUTFIT_SLOTS[k].map(v=>v[0]);for(const m of [true,false]){t.setMorph(m);step(80);const n=Math.max(all('hat').length,all('cape').length,all('top').length,all('weapon').length,all('skin').length);for(let i=0;i<n;i++){t.setOutfit({hat:all('hat')[i%all('hat').length],cape:all('cape')[i%all('cape').length],top:all('top')[i%all('top').length],weapon:all('weapon')[i%all('weapon').length],skin:all('skin')[i%all('skin').length],flip:i%2===0});t.startAnimation('Run');step(3);t.stopAnimation();}}t.setOutfit({hat:'crown',cape:'red',top:'super',weapon:'sword',skin:'',flip:false});t.setMorph(true);step(80);});
check('upgrade pack: new weapons have perks and the bazooka shoots',()=>{for(const w of ['laser','katana','trident','scythe'])assert(t.perksFor({outfit:{weapon:w}}).melee===w,w);const pk=t.perksFor({outfit:{weapon:'bazooka'}});assert(pk.shoot==='bazooka');const me=t.currentCharacter(),bot=t.makeBot(t.BOTS.find(b=>b.name==='Astro Ace'));assert(t.startModGame(t.FIGHT,{p1:me,p2:bot,cpu:'hard'}));let i=0,shot=false;while(!t.game.over&&i<60*60){randomInputs('p1',i);step(1);i++;if(t.game.arena.shots.some(s=>s.type==='bazooka'))shot=true;}assert(shot,'bazooka never fired');t.backToDrawing();});
check('upgrade pack: Lava Lord and Astro Ace fight each other to a result',()=>{const a=t.makeBot(t.BOTS[4]),b=t.makeBot(t.BOTS[5]);assert(t.startModGame(t.FIGHT,{p1:a,p2:b}));let i=0;while(!t.game.over&&i<60*200){randomInputs('p1',i);randomInputs('p2',i+3);step(1);i++;}assert(t.game.over);t.backToDrawing();});
check('skins: picking a skin saves and survives reload',()=>{t.setOutfit({hat:'',cape:'',top:'',weapon:'',skin:'alien',flip:false});t.storageSave();t=boot();step(2);assert(t.outfit.skin==='alien','skin lost '+JSON.stringify(t.outfit));assert(t.validOutfit({skin:'nope'}).skin==='','bad skin not dropped');});
check('players: fresh boot has an id but no name yet, and no modal before the delay',()=>{store.delete('gas-player-v1');t=boot();step(2);assert(t.player.id&&!t.player.name,JSON.stringify(t.player));assert(doc.getElementById('modalTitle').textContent==='','modal open before the delay');});
check('players: name rules',()=>{assert(!t.cleanName('ab').ok);assert(!t.cleanName('fuckface').ok);const r=t.cleanName('  Pixel Fox 42!! ');assert(r.ok&&r.name==='Pixel Fox 42',JSON.stringify(r));assert(t.setPlayerName('GabeTheGreat').ok);assert(t.player.name==='GabeTheGreat');assert(JSON.parse(store.get('gas-player-v1')).name==='GabeTheGreat');assert(byId.get('player').textContent==='👤 GabeTheGreat',byId.get('player').textContent);});
check('leaderboard: local-only mode shows this device scores',()=>{t.LB.url='';t.LB.apiKey='';assert(t.openLeaderboard('brawl'));assert(/Monster Brawl/.test(byId.get('modalTitle').textContent));t.closeModal();assert(!t.openLeaderboard('nope'));});
check('leaderboard: scores upload as PUT and the top 10 renders with me highlighted',()=>{const calls=[];t.LB.url='https://example-rtdb.firebaseio.com';t.setFetch((url,o)=>{calls.push({url,o});if(o&&o.method==='PUT')return Promise.resolve({ok:true,json:()=>Promise.resolve({})});return Promise.resolve({ok:true,json:()=>Promise.resolve({a1:{name:'Zed',score:50},[t.player.id]:{name:'GabeTheGreat',score:120},b2:{name:'Amy',score:90},bad:{name:5,score:'x'}})});});assert(t.lbReport('brawl',120));assert(!t.lbReport('brawl',100),'worse score reported');return Promise.resolve().then(()=>t.lbFlush()).then(()=>{const put=calls.find(c=>c.o&&c.o.method==='PUT'&&c.url.indexOf('/scores/brawl/')>0);assert(put,'no brawl PUT in '+calls.map(c=>c.url).join(','));assert(put.url.indexOf('/scores/brawl/'+t.player.id+'.json')>0,put.url);const body=JSON.parse(put.o.body);assert(body.name==='GabeTheGreat'&&body.score===120&&body.at&&body.at['.sv']==='timestamp',put.o.body);assert(t.lbQueue.length===0,'queue not drained');return t.lbTop('brawl');}).then(rows=>{assert(rows.length===3&&rows[0].name==='GabeTheGreat'&&rows[2].name==='Zed',JSON.stringify(rows));assert(t.lbCache.brawl.rows.length===3);const g=calls.find(c=>!c.o||!c.o.method);assert(/orderBy="score"&limitToLast=10/.test(g.url),g.url);});});
check('leaderboard: offline keeps the queue and shows the cached top 10',()=>{t.setOnline(false);assert(t.lbReport('hoops',31));assert(t.lbQueue.some(q=>q.key==='hoops'),'not queued');t.openLeaderboard('brawl');const txt=JSON.stringify(byId.get('modalBody').children.map(c=>c.textContent||c.children.map(x=>x.textContent).join('|')));assert(/offline/.test(txt),txt);t.closeModal();t.setOnline(true);t.setFetch(()=>Promise.reject(new Error('down')));t.openLeaderboard('hoops');t.closeModal();});
check('leaderboard: House Hunt is lower-is-better and uses limitToFirst',()=>{delete t.lbLocal.house;assert(t.lbReport('house',95));assert(t.lbReport('house',80),'faster time should count');assert(!t.lbReport('house',90),'slower time counted');const calls=[];t.setFetch(url=>{calls.push(url);return Promise.resolve({ok:true,json:()=>Promise.resolve({})});});return t.lbTop('house').then(()=>{assert(/limitToFirst=10/.test(calls[0]),calls[0]);});});
check('leaderboard: finishing Monster Brawl reports its score',()=>{t.startModGame(t.BRAWL,{});const A=t.game.arena;A.score=777;t.finishMod(t.game,true,'x','y');assert(t.lbQueue.some(q=>q.key==='brawl'&&q.score===777)||t.lbCache,'brawl not queued');t.backToDrawing();t.LB.url='';});
check('leaderboard auth: anonymous sign-up, token reuse, refresh, and uid in the write path',()=>{t.LB.url='https://example-rtdb.firebaseio.com';t.LB.apiKey='KEY123';t.setAuthState(null);const calls=[];t.setFetch((url,o)=>{calls.push({url,o});if(url.indexOf('accounts:signUp')>0)return Promise.resolve({ok:true,json:()=>Promise.resolve({localId:'uidABC',idToken:'tok1',refreshToken:'ref1',expiresIn:'3600'})});if(url.indexOf('securetoken')>0)return Promise.resolve({ok:true,json:()=>Promise.resolve({user_id:'uidABC',id_token:'tok2',refresh_token:'ref2',expires_in:'3600'})});return Promise.resolve({ok:true,json:()=>Promise.resolve({})});});return t.lbAuth().then(tok=>{assert(tok==='tok1',tok);assert(t.lbUid()==='uidABC');assert(JSON.parse(store.get('gas-lb-auth-v1')).uid==='uidABC');return t.lbAuth();}).then(tok=>{assert(tok==='tok1','should reuse the cached token');assert(calls.length===1,'extra auth calls '+calls.length);t.lbAuthState.exp=Date.now()-1;return t.lbAuth();}).then(tok=>{assert(tok==='tok2','refresh did not run');delete t.lbLocal.plane;assert(t.lbReport('plane',55));return t.lbFlush();}).then(()=>{const put=calls.find(c=>c.o&&c.o.method==='PUT'&&c.url.indexOf('/scores/plane/')>0);assert(put,'no plane PUT');assert(put.url.indexOf('/scores/plane/uidABC.json?auth=tok2')>0,put.url);});});
check('leaderboard auth: a dead refresh token falls back to a fresh anonymous sign-up',()=>{const calls=[];t.setFetch((url,o)=>{calls.push(url);if(url.indexOf('securetoken')>0)return Promise.resolve({ok:false,status:400,json:()=>Promise.resolve({})});if(url.indexOf('accounts:signUp')>0)return Promise.resolve({ok:true,json:()=>Promise.resolve({localId:'uidNEW',idToken:'tok9',refreshToken:'ref9',expiresIn:'3600'})});return Promise.resolve({ok:true,json:()=>Promise.resolve({})});});t.lbAuthState.exp=0;return t.lbAuth().then(tok=>{assert(tok==='tok9'&&t.lbUid()==='uidNEW',tok+' '+t.lbUid());t.LB.url='';t.LB.apiKey='';t.setAuthState(null);});});
check('Space Quest: shield blocks acid rain but drains and recharges',()=>{assert(t.startModGame(t.QUEST,{world:3}));const g=t.game,q=g.q;assert(q.world.hazard==='rain');step(5);q.p.inv=0;t.inputDown('p1','c','k');step(2);assert(q.shieldOn,'shield not up');const hearts=g.hearts;q.drops.length=0;q.drops.push({x:q.p.x,y:q.p.y-100,vy:0,r:12});step(2);assert(g.hearts===hearts,'shield let the drop through');assert(q.drops.length===0,'drop not absorbed');const e0=q.shieldE;step(60);assert(q.shieldE<e0,'shield did not drain');t.inputUp('p1','c','k');step(2);assert(!q.shieldOn);const e1=q.shieldE;step(60);assert(q.shieldE>e1,'shield did not recharge');t.backToDrawing();});
check('Space Quest: shield runs out, locks, and the rain hurts again',()=>{assert(t.startModGame(t.QUEST,{world:3}));const g=t.game,q=g.q;step(5);t.inputDown('p1','c','k');q.shieldE=.02;step(5);assert(!q.shieldOn&&q.shieldLock,'shield should have run out');q.p.inv=0;const hearts=g.hearts;q.drops.length=0;q.drops.push({x:q.p.x,y:q.p.y-100,vy:0,r:12});step(2);assert(g.hearts===hearts-1,'rain should hurt with an empty shield');t.inputUp('p1','c','k');t.backToDrawing();});
check('Space Quest: a platform overhead stops the rain',()=>{assert(t.startModGame(t.QUEST,{world:3}));const g=t.game,q=g.q;step(5);q.p.inv=0;q.level.plats.length=0;q.level.plats.push({x:q.p.x-80,y:q.p.y-260,w:160});q.drops.length=0;const d={x:q.p.x,y:q.p.y-320,vy:300,r:12};q.drops.push(d);const hearts=g.hearts;for(let i=0;i<90;i++){q.p.vx=0;q.p.inv=0;step(1);}assert(g.hearts===hearts,'drop got through the platform');assert(!q.drops.includes(d),'drop should have splashed on the platform');t.backToDrawing();});
check('Space Quest: enemies still hurt through the shield',()=>{assert(t.startModGame(t.QUEST,{world:0}));const g=t.game,q=g.q;step(5);t.inputDown('p1','c','k');step(2);q.p.inv=0;const hearts=g.hearts;q.level.enemies.length=0;q.level.enemies.push({x:q.p.x,origin:q.p.x,y:640,v:0,range:10,alive:true});q.p.y=640;q.p.vy=0;step(2);assert(g.hearts===hearts-1,'enemy should hurt even with the shield');t.inputUp('p1','c','k');t.backToDrawing();});
check('Power Moves: every move has a style, Surprise picks a new move, Combo chains four and stops',()=>{for(const m of t.MOVES)assert(t.MOVE_STYLE[m],'no style for '+m);t.stopAnimation();t.surpriseMove();assert(t.MOVES.includes(t.animation),'surprise did not start a move');const first=t.animation;t.surpriseMove();assert(t.animation&&t.animation!==first,'surprise repeated the same move');t.stopAnimation();t.startCombo();assert(t.comboTimer,'combo not running');assert(t.MOVES.includes(t.animation));step(5);t.stopCombo();assert(!t.comboTimer,'combo did not stop');t.stopAnimation();});
check('offline app: manifest, icons and service worker are wired up',()=>{const root=process.env.GAS_ROOT||path.join(__dirname,'..');const m=JSON.parse(fs.readFileSync(path.join(root,'manifest.webmanifest'),'utf8'));assert(m.display==='standalone'&&m.start_url==='./',JSON.stringify(m));for(const i of m.icons)assert(fs.existsSync(path.join(root,i.src)),'missing '+i.src);assert(/<link rel="manifest" href="manifest.webmanifest">/.test(html));assert(/<link rel="apple-touch-icon" href="icons\/apple-touch-icon.png">/.test(html));assert(/serviceWorker\.register\('sw\.js'\)/.test(html));const sw=fs.readFileSync(path.join(root,'sw.js'),'utf8');const files=JSON.parse(sw.match(/APP_FILES = (\[[^\]]*\])/)[1].replace(/'/g,'"'));for(const f of files)if(f!=='./')assert(fs.existsSync(path.join(root,f)),'sw caches a missing file '+f);for(const i of m.icons)assert(files.includes('./'+i.src),'sw does not cache '+i.src);});
check('Slingshot Siege: all 60 levels generate sensible plans that do not overlap',()=>{for(let wi=0;wi<t.SL_WORLDS.length;wi++)for(let li=0;li<t.SL_LEVELS;li++){const P=t.slPlan(wi,li),tag=wi+'-'+li;assert(P.mons.length>=1&&P.shots>=3&&P.shots<=7&&P.shots>P.mons.length-1,tag+' shots '+P.shots+' mons '+P.mons.length);if(li===t.SL_LEVELS-1)assert(P.mons.some(m=>m.boss),tag+' boss level has no boss');const box=q=>q.r?{x:q.x-q.r,y:q.y-q.r,r:q.x+q.r,b:q.y+q.r}:{x:q.x-q.w/2,y:q.y-q.h/2,r:q.x+q.w/2,b:q.y+q.h/2};const all=P.blocks.concat(P.mons).concat(P.peds).map(box);for(const b of all)assert(b.x>480&&b.r<1280&&b.y>0&&b.b<=641,tag+' out of bounds '+JSON.stringify(b));for(let i=0;i<all.length;i++)for(let j=i+1;j<all.length;j++){const a=all[i],b=all[j];assert(Math.min(a.r,b.r)-Math.max(a.x,b.x)<=1||Math.min(a.b,b.b)-Math.max(a.y,b.y)<=1,tag+' overlap '+JSON.stringify([a,b]));}}assert(JSON.stringify(t.slPlan(2,5))===JSON.stringify(t.slPlan(2,5)),'levels must be the same every time');});
check('Slingshot Siege: every level stands still before the first shot',()=>{t.setStrokes(stick());for(let wi=0;wi<t.SL_WORLDS.length;wi++)for(let li=0;li<t.SL_LEVELS;li++){assert(t.startModGame(t.SLING,{world:wi,level:li}),'start '+wi+'-'+li);const S=t.game.s,p0=S.blocks.map(b=>({...b.position}));step(150);assert(!S.mons.some(b=>b.sl.dead)&&!S.blocks.some(b=>b.sl.dead),'something broke by itself in '+wi+'-'+li);S.blocks.forEach((b,i)=>assert(Math.hypot(b.position.x-p0[i].x,b.position.y-p0[i].y)<6,'block drifted in '+wi+'-'+li));t.backToDrawing();}});
check('Slingshot Siege: the aiming dots match the real flight',()=>{t.setStrokes(stick());t.startModGame(t.SLING,{world:3,level:0});const g=t.game,S=g.s,vx=12,vy=-9,gy=S.w.gravity*.001*t.SL_STEP*t.SL_STEP;const h=t.slLaunch(g,vx,vy);let x=t.SL_POUCH.x,y=t.SL_POUCH.y,ux=vx,uy=vy;for(let i=0;i<40;i++){S.M.Engine.update(S.eng,t.SL_STEP);ux*=1-t.SL_AIR;uy=uy*(1-t.SL_AIR)+gy;x+=ux;y+=uy;}assert(Math.hypot(h.position.x-x,h.position.y-y)<12,'preview off by '+Math.hypot(h.position.x-x,h.position.y-y).toFixed(1));t.backToDrawing();});
check('Slingshot Siege: dragging back and letting go launches the hero to the right',()=>{t.startModGame(t.SLING,{world:0,level:0});const g=t.game;g.mod.pointer(g,'down',{x:300,y:450});g.mod.pointer(g,'move',{x:180,y:520});g.mod.pointer(g,'up',{x:180,y:520});assert(g.s.heroes.length===1&&g.s.shotsUsed===1,'no launch');const v=g.s.heroes[0].velocity;assert(v.x>5&&v.y<-3,JSON.stringify(v));g.mod.pointer(g,'down',{x:300,y:450});g.mod.pointer(g,'up',{x:295,y:452});assert(g.s.shotsUsed===1,'a tiny tap must not launch');t.backToDrawing();});
check('Slingshot Siege: a hero smashing into a monster knocks it out and scores',()=>{t.startModGame(t.SLING,{world:0,level:0});const g=t.game,S=g.s,m=S.mons[0],h=t.slLaunch(g,1,-1);S.M.Body.setPosition(h,{x:m.position.x-120,y:m.position.y});S.M.Body.setVelocity(h,{x:16,y:0});step(30);assert(m.sl.dead,'monster survived');assert(S.score>=500,'score '+S.score);t.backToDrawing();});
check('Slingshot Siege: clearing a level saves stars, unlocks the next level, and Next level works',()=>{t.slProg().stars={};t.startModGame(t.SLING,{world:0,level:0});const g=t.game;for(const b of g.s.mons)t.slKill(g,b);step(100);assert(g.over&&g.won,'not won');assert(t.slStars(0,0)===3,'stars '+t.slStars(0,0));assert(t.slUnlocked(0,1)&&!t.slUnlocked(0,2),'unlocking wrong');assert(byId.get('resultNext').hidden===false,'Next button hidden');g.next();assert(t.game&&t.game.s.li===1,'next level did not start');t.backToDrawing();assert(byId.get('resultNext').hidden===true);});
check('Slingshot Siege: running out of heroes loses, and a loss never removes stars',()=>{t.startModGame(t.SLING,{world:0,level:0});const g=t.game;g.s.shotsUsed=g.s.shots;g.s.phase='wait';step(260);assert(g.over&&!g.won,'should have lost');assert(byId.get('resultNext').hidden===true,'Next shown after a loss');assert(t.slStars(0,0)===3);t.backToDrawing();});
check('Slingshot Siege: stars unlock powers, and Boom and Hop work',()=>{t.slProg().stars={};t.startModGame(t.SLING,{world:0,level:2});let g=t.game;const boom=t.slButtons().find(b=>b.id==='boom');assert(boom.locked);t.slPick(g,boom);assert(g.s.power==='normal','locked power was picked');t.backToDrawing();for(let li=0;li<5;li++)t.slProg().stars['0-'+li]=3;assert(t.slTotalStars()===15);t.startModGame(t.SLING,{world:0,level:5});g=t.game;const S=g.s;t.slPick(g,t.slButtons().find(b=>b.id==='boom'));assert(S.power==='boom');const h=t.slLaunch(g,1,-1),m=S.mons[0];S.M.Body.setPosition(h,{x:m.position.x-40,y:m.position.y-30});assert(t.slUsePower(g),'boom did not fire');step(3);assert(m.sl.dead,'boom did not knock out the monster');assert(S.uses.boom===0&&S.power==='normal','boom should be used up');t.backToDrawing();for(let li=5;li<9;li++)t.slProg().stars['0-'+li]=3;t.startModGame(t.SLING,{world:0,level:9});g=t.game;t.slPick(g,t.slButtons().find(b=>b.id==='hop'));const hh=t.slLaunch(g,12,4);step(10);assert(t.slUsePower(g));assert(hh.velocity.y<-8,'hop did not go up '+hh.velocity.y);t.backToDrawing();});
check('Slingshot Siege: beating the boss opens the next world, and progress survives a reload',()=>{t.slProg().stars={};for(let li=0;li<12;li++)t.slProg().stars['0-'+li]=2;assert(t.slUnlocked(1,0)&&!t.slUnlocked(2,0));t.storageSave();t.startModGame(t.SLING,{world:1,level:0});const g=t.game;for(const b of g.s.mons)t.slKill(g,b);step(100);assert(g.won);t.backToDrawing();t=boot();step(2);assert(t.slStars(1,0)===3&&t.slTotalStars()===27,'stars lost on reload: '+t.slTotalStars());assert(t.openSlingMap()===undefined);t.closeModal();});
check('Slingshot Siege: total stars go on the leaderboard',()=>{t.setStrokes(stick());t.LB.url='';assert(t.LB_GAMES.sling);assert(t.localBest('sling')===t.slTotalStars());});
check('Backyard Defense: 30 levels have sensible, repeatable waves with a King Slime at the end of each place',()=>{for(let si=0;si<t.DF_SCENES.length;si++)for(let li=0;li<t.DF_LEVELS;li++){const P=t.dfPlan(si,li),tag=si+'-'+li;assert(P.spawns.length>=5,tag);assert(P.spawns.every((x,i)=>i===0||x.t>=P.spawns[i-1].t),'not sorted '+tag);assert(P.spawns.every(x=>x.lane>=0&&x.lane<5&&t.DF_MON[x.type]),'bad spawn '+tag);assert(P.spawns[0].t>=20,'no time to build '+tag);assert(P.spawns.some(x=>x.type==='boss')===(li===5),'boss placement '+tag);}assert(JSON.stringify(t.dfPlan(3,2))===JSON.stringify(t.dfPlan(3,2)));});
const dfStart=(si=0,li=0,cleared=0)=>{t.dfProg().stars={};for(let k=0;k<cleared;k++)t.dfProg().stars[Math.floor(k/6)+'-'+(k%6)]=1;t.setStrokes(stick());assert(t.startModGame(t.DEFENSE,{scene:si,level:li}));return t.game;};
check('Backyard Defense: placing guards costs energy, needs a free square, waits for the card, and locked guards cannot be placed',()=>{const g=dfStart(),S=g.s;assert(S.energy===150);assert(S.avail.map(d=>d.id).join()==='power,archer','avail '+S.avail.map(d=>d.id));assert(t.dfPlace(g,'archer',1,2));assert(S.energy===50);assert(!t.dfPlace(g,'power',1,2),'square taken');assert(!t.dfPlace(g,'archer',2,2),'not enough energy');assert(!t.dfPlace(g,'shield',3,3),'locked guard placed');assert(t.dfPlace(g,'power',0,2));assert(!t.dfPlace(g,'power',0,3),'card should be cooling down');assert(t.dfRemove(g,1,2));assert(S.guards.length===1&&S.energy===25,'take back '+S.energy);t.backToDrawing();});
check('Backyard Defense: tap a card then a square, or drag a card onto a square',()=>{const g=dfStart(),S=g.s,card=c=>{const i=S.avail.findIndex(d=>d.id===c);return{x:150+i*100+40,y:60};},sq=(c,l)=>({x:t.DF_X0+c*t.DF_CW+60,y:t.DF_Y0+l*t.DF_LH+40});g.mod.pointer(g,'down',card('power'));g.mod.pointer(g,'up',card('power'));assert(S.sel==='power');g.mod.pointer(g,'down',sq(0,1));assert(S.guards.length===1&&S.guards[0].lane===1&&S.guards[0].col===0,'tap-tap failed');g.mod.pointer(g,'down',card('archer'));g.mod.pointer(g,'move',sq(2,3));g.mod.pointer(g,'up',sq(2,3));assert(S.guards.length===2&&S.guards[1].col===2&&S.guards[1].lane===3,'drag failed');t.backToDrawing();});
check('Backyard Defense: archers pop slimes, slimes chew guards, and slimes reaching the clubhouse cost hearts',()=>{let g=dfStart(),S=g.s;t.dfPlace(g,'archer',1,0);S.mons.push({def:t.DF_MON.slime,lane:0,x:900,y:300,r:26,hp:100,max:100,speed:20,slowT:0,hitT:0,eating:false,seed:0});step(60*9);assert(S.kills===1,'archer did not pop the slime');S.mons.push({def:t.DF_MON.slime,lane:0,x:420,y:300,r:26,hp:99999,max:99999,speed:20,slowT:0,hitT:0,eating:false,seed:0});step(60*14);assert(!S.guards.some(q=>q.lane===0&&q.id==='archer'),'archer should have been chewed');step(60*15);assert(S.hearts===2,'hearts '+S.hearts);t.backToDrawing();g=dfStart();S=g.s;for(let i=0;i<3;i++)S.mons.push({def:t.DF_MON.speedy,lane:i,x:t.DF_X0+5,y:300,r:20,hp:70,max:70,speed:38,slowT:0,hitT:0,eating:false,seed:0});step(90);assert(g.over&&!g.won,'should lose with no hearts');assert(byId.get('resultNext').hidden===true);t.backToDrawing();});
check('Backyard Defense: saving the clubhouse gives stars, coins, a new guard, and the next level',()=>{const g=dfStart(0,0,0),S=g.s,c0=t.shopState().coins;S.next=S.plan.spawns.length;step(80);assert(g.over&&g.won,'not won');assert(t.dfStars(0,0)===3);assert(t.dfUnlocked(0,1)&&!t.dfUnlocked(0,2));assert(t.shopState().coins===c0+40,'coins '+(t.shopState().coins-c0));assert(/NEW GUARD: 🛡️ Shield Guard/.test(byId.get('resultText').textContent),byId.get('resultText').textContent);assert(/🪙 \+40/.test(byId.get('resultText').textContent));g.next();assert(t.game.s.li===1&&t.game.s.avail.some(d=>d.id==='shield'));t.backToDrawing();});
check('Backyard Defense: every guard can be drawn and does its job',()=>{const g=dfStart(4,0,30),S=g.s;assert(S.avail.length===t.DF_GUARDS.length);S.energy=99999;t.DF_GUARDS.forEach((d,i)=>{S.cool[d.id]=0;assert(t.dfPlace(g,d.id,i,i%5),'place '+d.id);});step(5);S.mons.push({def:t.DF_MON.brute,lane:3,x:720,y:300,r:38,hp:520,max:520,speed:13,slowT:0,hitT:0,eating:false,seed:0});step(60*20);assert(S.kills>=1,'brute survived the guards');t.backToDrawing();});
check('Gear Shop: coins come from every game, gear costs coins, and bought gear joins Gear Up',()=>{const p=t.shopState();p.coins=0;p.owned=[];t.buildOutfitRows();const names=()=>JSON.stringify(byId.get('outfit').children.map(r=>r.children.map(b=>b.textContent)));assert(!/Unicorn/.test(names()),'shop item visible before buying');assert(/in shop/.test(names()));t.startModGame(t.SLING,{world:0,level:0});const g=t.game;g.s.shotsUsed=g.s.shots;g.s.phase='wait';step(260);assert(g.over&&!g.won);assert(t.shopState().coins===2,'coins after a loss '+t.shopState().coins);t.backToDrawing();const uni=t.SHOP_ITEMS.find(i=>i.key==='unicorn');assert(!t.shopBuy(uni),'bought without coins');t.addCoins(100);assert(t.shopBuy(uni));assert(t.shopState().coins===22&&t.shopOwns('hat','unicorn'));assert(!t.shopBuy(uni),'bought twice');assert(/Unicorn/.test(names()),'bought hat not in Gear Up');t.storageSave();t=boot();step(2);assert(t.shopState().coins===22&&t.shopOwns('hat','unicorn'),'shop lost on reload');t.openShop();t.closeModal();});
check('Gear Shop: every shop item draws on a hero, and new weapons work in fights',()=>{t.setStrokes(stick());t.ensureRig();for(const it of t.SHOP_ITEMS){const base=t.currentCharacter(),ch={...base,outfit:t.validOutfit({...base.outfit,[it.slot]:it.key}),morph:true,morphT:1};assert(ch.outfit[it.slot]===it.key,'validOutfit dropped '+it.key);const c=doc.createElement('canvas');c.width=140;c.height=140;t.drawCharacterThumb(c,ch);}const mk=w=>t.perksFor({outfit:{weapon:w}});assert(mk('firesword').melee==='firesword'&&mk('icesword').melee==='icesword');assert(mk('starstaff').shoot==='wand');});
check('Hero Kart: every road starts flat, is the same every time, and never gets too steep to climb',()=>{for(const st of t.KT_STAGES){assert(t.ktGround(st,100)===t.ktGround(st,600),'start not flat '+st.name);let mx=0;for(let x=700;x<700+6000*t.KT_PX;x+=20)mx=Math.max(mx,Math.abs(t.ktGround(st,x+20)-t.ktGround(st,x))/20);assert(Math.atan(mx)*180/Math.PI<36,st.name+' too steep: '+(Math.atan(mx)*180/Math.PI).toFixed(1));assert(t.ktGround(st,12345)===t.ktGround(st,12345));}});
check('Hero Kart: holding Go drives forward, coins go to the wallet, and running out of battery ends the drive',()=>{const p=t.ktProg();for(const u of t.KT_UP)p.up[u.id]=0;t.setStrokes(stick());assert(t.startModGame(t.KART,{stage:0}));const g=t.game,S=g.s;t.inputDown('p1','right','test');step(60*12);t.inputUp('p1','right','test');assert(S.dist>60,'only '+S.dist.toFixed(0)+' m');assert(S.batt<S.battMax,'battery did not drain');S.got=7;const c0=t.shopState().coins;S.batt=0;step(60*14);assert(g.over,'did not end on empty battery');assert(t.shopState().coins===c0+t.withBuddy(S.got)&&S.got>=7,'coins not banked');assert(/Out of battery/.test(byId.get('resultTitle').textContent),byId.get('resultTitle').textContent);t.backToDrawing();});
check('Hero Kart: landing on your head ends the drive',()=>{t.startModGame(t.KART,{stage:0});const g=t.game,S=g.s,M=S.M,c=S.car.ch;for(const b of [c,S.car.wl,S.car.wr]){M.Body.setPosition(b,{x:b.position.x,y:b.position.y-160});}M.Body.setAngle(c,Math.PI);step(60*3);assert(g.over,'no crash');assert(/flipped/.test(byId.get('resultTitle').textContent));t.backToDrawing();});
check('Hero Kart: the Garage sells upgrades for coins, roads open at 600 m, and best distance saves',()=>{const p=t.ktProg();for(const u of t.KT_UP)p.up[u.id]=0;const sh=t.shopState();sh.coins=50;assert(!t.ktBuy('engine'),'bought without coins');sh.coins=1000;assert(t.ktBuy('engine')&&p.up.engine===1&&sh.coins===940);sh.coins=5000;for(let i=0;i<4;i++)t.ktBuy('engine');assert(p.up.engine===5&&!t.ktBuy('engine'),'went past max');p.best={};assert(!t.ktUnlocked(1));p.best[0]=600;assert(t.ktUnlocked(1)&&!t.ktUnlocked(2));assert(t.ktStarsFor(299)===0&&t.ktStarsFor(300)===1&&t.ktStarsFor(1000)===2&&t.ktStarsFor(2500)===3);t.openKart();t.closeModal();});
const gqBoard=(S,f)=>{for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(S.grid[r][c])Object.assign(S.grid[r][c],{c:f(r,c),sp:null,dy:0});};
check('Gem Quest: 30 levels with sensible goals, and boards start with no matches but at least one move',()=>{for(let wi=0;wi<3;wi++)for(let li=0;li<10;li++){const L=t.gqLevel(wi,li);assert(L.moves>=15&&L.goal&&L.goal.n>0,wi+'-'+li);for(const k in L.ice)assert(!L.holes[k],'ice on a hole '+wi+'-'+li);}t.setStrokes(stick());for(let k=0;k<5;k++){t.startModGame(t.GEMS,{world:2,level:5,seed:k});const S=t.game.s;assert(!t.gqFindRuns(S).length,'starts with a match');assert(t.gqMoves(S).length>0,'no moves');t.backToDrawing();}});
check('Gem Quest: a swap that matches clears, refills, and costs a move; a bad swap does not',()=>{t.startModGame(t.GEMS,{world:0,level:0,seed:3});const g=t.game,S=g.s,mv=t.gqMoves(S)[0],m0=S.moves;assert(t.gqTrySwap(g,mv[0],mv[1],true));assert(S.moves===m0-1&&S.score>0);for(let r=0;r<8;r++)for(let c=0;c<8;c++)assert(S.grid[r][c],'hole left at '+r+','+c);assert(!t.gqFindRuns(S).length,'board not settled');gqBoard(S,(r,c)=>(r*2+c)%5);assert(!t.gqTrySwap(g,[0,0],[0,1],true),'bad swap accepted');assert(S.moves===m0-1);t.backToDrawing();});
check('Gem Quest: 4 in a row makes a Line Stone, 5 makes a Star Stone, and a Star Stone clears a whole colour',()=>{t.startModGame(t.GEMS,{world:0,level:2,seed:5});const g=t.game,S=g.s;gqBoard(S,(r,c)=>(r*2+c)%5);for(const c of [0,1,3])S.grid[2][c].c=4;S.grid[3][2].c=4;S.grid[2][2].c=3;const made=S.made;assert(t.gqTrySwap(g,[3,2],[2,2],true),'4-match swap refused');assert(S.made>made,'no special stone made');gqBoard(S,(r,c)=>(r*2+c)%5);for(const c of [0,1,3,4])S.grid[5][c].c=2;S.grid[6][2].c=2;S.grid[5][2].c=1;const m2=S.made;assert(t.gqTrySwap(g,[6,2],[5,2],true));assert(S.made>m2,'no star made');t.backToDrawing();t.startModGame(t.GEMS,{world:0,level:2,seed:6});const g2=t.game,S2=g2.s,k=S2.L.goal.color;gqBoard(S2,(r,c)=>(r*2+c)%5);let count=0;for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(S2.grid[r][c].c===k)count++;S2.grid[0][0].sp='star';S2.grid[0][0].c=-1;const nb=S2.grid[0][1].c===k?[0,1]:[1,0];S2.grid[nb[0]][nb[1]].c=k;const c0=S2.collected;assert(t.gqTrySwap(g2,[0,0],nb,true),'star swap refused');assert(S2.collected-c0>=count-1,'star cleared '+(S2.collected-c0)+' of '+count);t.backToDrawing();});
check('Gem Quest: ice cracks, Hero Blast is free, and the level is won or lost on the goal and moves',()=>{t.startModGame(t.GEMS,{world:0,level:1,seed:2});let g=t.game,S=g.s;assert(S.L.goal.type==='ice'&&S.iceLeft>0);const key=Object.keys(S.L.ice)[0].split(',').map(Number),i0=S.iceLeft;t.gqClear(S,[key]);t.gqGravity(S);assert(S.iceLeft===i0-1,'ice did not crack');S.power=t.GQ_BLAST;const m0=S.moves,s0=S.score;assert(t.gqBlast(g,true));assert(S.power<t.GQ_BLAST&&S.moves===m0&&S.score>s0,'blast');S.iceLeft=0;const mv=t.gqMoves(S)[0];t.gqTrySwap(g,mv[0],mv[1],true);assert(g.over&&g.won,'not won');assert(t.gpStars('gems',0,1)>=1&&t.gpStars('gems',0,1)<=3);assert(byId.get('resultNext').hidden===false);t.backToDrawing();t.startModGame(t.GEMS,{world:0,level:3,seed:4});g=t.game;S=g.s;S.moves=1;const mv2=t.gqMoves(S)[0];t.gqTrySwap(g,mv2[0],mv2[1],true);assert(g.over&&!g.won,'should be out of moves');t.backToDrawing();});
check('Gem Quest: dragging a stone swaps it, with the animation running to the end',()=>{t.startModGame(t.GEMS,{world:0,level:0,seed:9});const g=t.game,S=g.s,[a,b]=t.gqMoves(S)[0],pt=([r,c])=>({x:t.GQ_X0+c*t.GQ_CELL+37,y:t.GQ_Y0+r*t.GQ_CELL+37}),m0=S.moves;g.mod.pointer(g,'down',pt(a));g.mod.pointer(g,'move',pt(b));assert(S.moves===m0-1,'drag did not swap');step(60*4);assert(S.phase==='idle','stuck in '+S.phase);assert(!t.gqFindRuns(S).length);for(let r=0;r<8;r++)for(let c=0;c<8;c++)assert(S.grid[r][c]&&S.grid[r][c].dy===0,'stone not landed');t.openGems();t.closeModal();t.backToDrawing();});
check('Beat Run: 18 songs, faster each time, with a quiet count-in and never two big jumps in a row',()=>{let last=0;for(let si=0;si<3;si++)for(let li=0;li<6;li++){const S=t.brSong(si,li);assert(S.beats.slice(0,8).every(k=>k==='.'),'no count-in');for(let i=1;i<S.beats.length;i++)assert(!('bg'.includes(S.beats[i-1])&&S.beats[i]!=='.'),'something right after a big jump '+si+'-'+li);assert(JSON.stringify(t.brSong(si,li))===JSON.stringify(S));if(li)assert(S.bpm>last,'tempo should rise');last=S.bpm;}});
const brPlay=(si,li,off)=>{t.setStrokes(stick());t.startModGame(t.BEATRUN,{stage:si,level:li});const g=t.game,S=g.s,beats=S.song.beats;let next=0,hold=-1;for(let f=0;f<60*300&&!g.over;f++){if(off!=null){while(next<beats.length&&beats[next]==='.')next++;if(next<beats.length&&S.beatPos>=next+off){g.mod.pointer(g,'down',{x:0,y:0});hold=beats[next]==='s'?S.beatPos+.05:S.beatPos+.4;next++;}if(hold>=0&&S.beatPos>=hold){g.mod.pointer(g,'up',{x:0,y:0});hold=-1;}}step(1);}return g;};
check('Beat Run: jumping on the beat finishes with all hearts and stars; not jumping loses',()=>{let g=brPlay(0,0,0);assert(g.over&&g.won&&g.s.hearts===3,'perfect run did not 3-heart');assert(t.gpStars('beat',0,0)===3);assert(g.s.perfect>=5,'perfects '+g.s.perfect);t.backToDrawing();g=brPlay(1,3,.1);assert(g.over&&g.won,'slightly late should still finish');t.backToDrawing();g=brPlay(0,1,null);assert(g.over&&!g.won,'no jumping should lose');t.backToDrawing();});
check('Beat Run: a tap is a small jump, holding makes a big jump, and keys work too',()=>{t.startModGame(t.BEATRUN,{stage:0,level:0});const g=t.game,S=g.s;g.mod.pointer(g,'down',{x:0,y:0});g.mod.pointer(g,'up',{x:0,y:0});step(5);assert(S.jump&&!S.jump.long,'tap made a big jump');step(60);assert(!S.jump,'did not land');g.mod.pointer(g,'down',{x:0,y:0});step(40);assert(S.jump&&S.jump.long,'hold did not make a big jump');g.mod.pointer(g,'up',{x:0,y:0});step(80);t.inputDown('p1','up','key:Space');step(2);assert(S.jump,'Space did not jump');t.inputUp('p1','up','key:Space');t.backToDrawing();t.openBeat();t.closeModal();});
check('Draw Path: 24 puzzles that need drawing, can be won, and have 3 reachable gems',()=>{for(let wi=0;wi<3;wi++)for(let li=0;li<8;li++){const L=t.dpLevel(wi,li),tag=wi+'-'+li;assert(L&&L.sol&&L.gems.length===3&&L.ink>0,tag);assert(t.dpSimulate(L,[]).status!=='won','wins without drawing '+tag);const r=t.dpSimulate(L,[L.sol.map(([x,y])=>({x,y}))]);assert(r.status==='won'&&r.gems===3,'saved solution fails '+tag+' '+r.status+' '+r.gems);assert(t.dpInkLen([L.sol.map(([x,y])=>({x,y}))])<L.ink,'not enough ink '+tag);for(const [x,y] of L.sol)assert(!t.dpInZone(L,x,y),'solution in a no-ink zone '+tag);}});
const dpDraw=(g,pts)=>{g.mod.pointer(g,'down',pts[0]);for(const p of pts.slice(1))g.mod.pointer(g,'move',p);g.mod.pointer(g,'up',pts[pts.length-1]);};
check('Draw Path: drawing the path with a finger and pressing GO rescues the pet',()=>{t.setStrokes(stick());assert(t.startModGame(t.DRAWPATH,{world:0,level:2}));const g=t.game,S=g.s,pts=[];const sol=S.L.sol;for(let i=1;i<sol.length;i++){const [ax,ay]=sol[i-1],[bx,by]=sol[i],n=Math.ceil(Math.hypot(bx-ax,by-ay)/14);for(let k=(i===1?0:1);k<=n;k++)pts.push({x:ax+(bx-ax)*k/n,y:ay+(by-ay)*k/n});}dpDraw(g,pts);assert(S.strokes.length===1,'stroke not kept');g.mod.pointer(g,'down',{x:1180,y:50});assert(S.phase==='roll','GO did not start');step(60*15);assert(g.over&&g.won,'pet not rescued: '+S.phase+' '+S.E.status);assert(t.gpStars('path',0,2)>=2,'stars '+t.gpStars('path',0,2));t.backToDrawing();});
check('Draw Path: no-ink zones, the ink limit, Undo, Clear, and trying again after a fall',()=>{t.startModGame(t.DRAWPATH,{world:2,level:7});const g=t.game,S=g.s,z=S.L.nodraw[0];g.mod.pointer(g,'down',{x:z[0]+z[2]/2,y:z[1]+z[3]/2});assert(!S.strokes.length,'drew inside a no-ink zone');const long=[];for(let i=0;i<400;i++)long.push({x:40+(i%2)*1100,y:300+i*0.5});dpDraw(g,long.slice(0,6));assert(S.strokes.length>=1);const used=t.dpInkLen(S.strokes);assert(used<=S.L.ink+1,'used more ink than allowed');g.mod.pointer(g,'down',{x:1010,y:50});assert(S.strokes.length===0,'undo failed');dpDraw(g,[{x:300,y:600},{x:500,y:600}]);dpDraw(g,[{x:600,y:600},{x:700,y:600}]);g.mod.pointer(g,'down',{x:840,y:50});assert(S.strokes.length===0,'clear failed');g.mod.pointer(g,'down',{x:1180,y:50});step(60*6);assert(S.phase==='draw'&&!g.over,'should be back to drawing after the fall, got '+S.phase);assert(S.tries===1);t.backToDrawing();t.openPath();t.closeModal();});
check('Monster Pals: 25 pals in 5 places, places open as you find pals, and Copy Dance makes a friend',()=>{assert(t.PL_PALS.length===25,'pal count');for(const h of t.PL_HABITATS)assert(t.PL_PALS.filter(p=>p.hab===h.id).length>=4,h.id);const P=t.plProg();P.have={};P.buddy=null;assert(t.plOpen(0)&&!t.plOpen(1),'places open wrong: '+t.plCount());assert(t.startModGame(t.PALS,{habitat:0,pal:0,mode:'dance',seed:3}),'pals did not start');const g=t.game,S=g.s;for(let f=0;f<60*60&&!g.over;f++){step(1);if(S.phase==='play'&&S.sub==='input'){const b=t.plDanceButtons().find(b=>b.id===S.seq[S.inputs.length]);g.mod.pointer(g,'down',{x:b.x+5,y:b.y+5});}}assert(g.over&&g.won,'dance not won');assert(P.have[0]===1&&t.plCount()===1,'have '+JSON.stringify(P.have));assert(/Meet another pal/.test(byId.get('resultNext').textContent));t.backToDrawing();P.have[1]=1;P.have[2]=1;assert(t.plOpen(1),'beach should open at 3 pals');});
check('Monster Pals: Peekaboo and Snack Toss can be won, wrong taps make a pal shy, and meeting a friend again raises friendship',()=>{const P=t.plProg();t.startModGame(t.PALS,{habitat:0,pal:0,mode:'peek',seed:5});let g=t.game,S=g.s;for(let f=0;f<60*60&&!g.over;f++){step(1);if(S.phase==='play'&&S.peekAt>=0&&S.peekT<S.peekLen-.15){const b=t.plBushes()[S.peekAt];g.mod.pointer(g,'down',{x:b.x,y:b.y-60});}}assert(g.won,'peek not won');assert(P.have[0]===2,'friendship did not rise');t.backToDrawing();t.startModGame(t.PALS,{habitat:0,pal:1,mode:'peek',seed:6});g=t.game;S=g.s;step(60*3);for(let k=0;k<3;k++){const i=(S.peekAt+1)%4,b=t.plBushes()[i<0?0:i];g.mod.pointer(g,'down',{x:b.x,y:b.y-60});}step(60*3);assert(g.over&&!g.won,'three wrong taps should make it shy');t.backToDrawing();t.startModGame(t.PALS,{habitat:0,pal:3,mode:'toss',seed:7});g=t.game;S=g.s;for(let f=0;f<60*60&&!g.over;f++){step(1);if(S.phase==='play'&&!S.shots.some(s=>!s.done)&&f%6===0)g.mod.pointer(g,'down',{x:S.px+S.dir*S.speed*.5,y:440});}assert(g.won,'snack toss not won');t.backToDrawing();});
check('Monster Pals: a Buddy adds 10% coins to every game',()=>{const P=t.plProg();P.buddy=null;assert(t.withBuddy(20)===20);P.have[0]=1;P.buddy=0;assert(t.plBuddy().name==='Blip');assert(t.withBuddy(20)===22&&t.withBuddy(4)===5&&t.withBuddy(0)===0);const c0=t.shopState().coins;t.startModGame(t.SLING,{world:0,level:0});const g=t.game;g.s.shotsUsed=g.s.shots;g.s.phase='wait';step(260);assert(t.shopState().coins===c0+3,'buddy bonus not paid: '+(t.shopState().coins-c0));assert(/Buddy bonus/.test(byId.get('resultText').textContent));t.backToDrawing();t.openPals();t.closeModal();P.buddy=null;});
check('Endless Dash upgrades: bought in the Gear Shop; shield, jetpack, magnet and rocket start work; coins grow with distance',()=>{t.setStrokes(stick());const sh=t.shopState();sh.owned=sh.owned.filter(x=>!x.startsWith('dash:'));assert(t.startGame('dash'));let g=t.game;assert(!g.shield&&g.maxJumps===2&&!g.zoom);t.backToDrawing();sh.coins=1000;for(const u of t.DASH_UPS)assert(t.shopBuy({slot:'dash',key:u.id,name:u.name,price:u.price}),'could not buy '+u.id);assert(sh.coins===1000-t.DASH_UPS.reduce((a,u)=>a+u.price,0));assert(t.startGame('dash'));g=t.game;assert(g.shield===1&&g.maxJumps===4&&g.zoom>0&&g.magnet);step(10);assert(g.vx===760,'no rocket start');const x0=g.x;step(60*4);assert(g.vx<760,'rocket start never ended');for(let i=0;i<4;i++){t.jump();step(2);}assert(g.jumps===4,'jetpack boosts: '+g.jumps);g.invulnerable=0;g.pickups.push({x:g.x+150,y:g.y-80,taken:false});const h=g.hearts;g.enemies.push({x:g.x,origin:g.x,y:640,v:0,range:0});g.y=640;g.vy=0;step(3);assert(g.hearts===h&&g.shield===0,'shield did not block');t.backToDrawing();const c0=sh.coins;t.startGame('dash');g=t.game;g.distance=12*600;g.stars=4;g.hearts=1;g.invulnerable=0;g.zoom=0;g.enemies.push({x:g.x,origin:g.x,y:640,v:0,range:0});g.y=640;g.vy=0;g.shield=0;step(5);assert(g.over,'run did not end');assert(sh.coins-c0>=4+Math.floor(640/25),'dash coins '+(sh.coins-c0));t.backToDrawing();t.openShop();t.closeModal();});
check('How to play: every big game has a demo that plays itself, can be skipped, and changes nothing',()=>{t.setStrokes(stick());const sh=t.shopState();sh.coins=123;const before=JSON.stringify(t.progress);for(const key of Object.keys(t.TUTORIALS)){assert(t.tutStart(key),'demo did not start: '+key);const g=t.game;assert(g.tut);step(Math.ceil(t.TUTORIALS[key].length*60)+30);assert(g.tut.done,'demo did not finish: '+key);assert(g.tut.actions>0,'demo did nothing: '+key);assert(/Now you try/.test(byId.get('resultTitle').textContent));assert(byId.get('resultNext').hidden===false&&/play/i.test(byId.get('resultNext').textContent));assert(JSON.stringify(t.progress)===before,'demo changed progress: '+key);t.backToDrawing();}assert(t.tutStart('sling'));step(30);const g=t.game;t.inputDown('p1','right','key:x');assert(!t.game.s.kb,'keys should be ignored during a demo');g.mod.pointer;t.backToDrawing();assert(JSON.stringify(t.progress)===before,'leaving a demo early changed progress');});
check('How to play: the demos actually play (slingshot hit, guards placed, kart drove, gems swapped, jumps made, path drawn, pal befriended)',()=>{const run=k=>{t.tutStart(k);const g=t.game;step(Math.ceil(t.TUTORIALS[k].length*60)+30);return g;};let g=run('sling');assert(g.s.shotsUsed===1&&g.s.mons.every(b=>b.sl.dead),'sling demo missed');t.backToDrawing();g=run('defense');assert(g.s.guards.length>=6,'guards '+g.s.guards.length);t.backToDrawing();g=run('kart');assert(g.s.dist>80,'kart '+g.s.dist);t.backToDrawing();g=run('gems');assert(g.s.moves<g.s.L.moves,'no gem swaps');t.backToDrawing();g=run('beat');assert(g.s.perfect>=5&&g.s.hearts===3,'beat '+g.s.perfect+' '+g.s.hearts);t.backToDrawing();g=run('path');assert(g.tut.won,'path demo did not rescue');t.backToDrawing();g=run('pals');assert(g.tut.won,'pals demo did not befriend');t.backToDrawing();});
check('Music: 7 original built-in tracks play, switch, show in the button, and are remembered',()=>{assert(t.TRACK_LIST.length===7);t.unlockAudio();for(const T of t.TRACK_LIST){t.setMusicTrack(T.id);assert(t.musicTrack===T.id&&t.musicMode==='groove');for(let i=0;i<40;i++){t.audio.currentTime+=.1;t.musicTick();}assert(byId.get('music').textContent==='🎵 '+T.short,byId.get('music').textContent);if(T.id!=='groove')assert(Object.keys(T.mel).length>=8,'melody too short '+T.id);}t.setMusicTrack('chill');t.storageSave();t=boot();step(2);assert(t.musicTrack==='chill','track not remembered: '+t.musicTrack);t.openMusic();const btns=byId.get('modalBody').children.flatMap(c=>c.children||[]).filter(b=>b.dataset&&(b.dataset.track||b.dataset.mode));assert(btns.length===9,'music panel buttons '+btns.length);assert(btns.find(b=>b.dataset.track==='chill').getAttribute('aria-pressed')==='true');t.closeModal();t.setMusicTrack('groove');t.musicPause();});
check('Seasons: each event switches on only on its dates, and New Year wraps around January',()=>{const on=(id,m,d)=>t.seasonOpenOn(t.SEASONS[id],new Date(2026,m-1,d));assert(on('halloween',10,1)&&on('halloween',10,31)&&on('halloween',11,2)&&!on('halloween',11,3)&&!on('halloween',9,30));assert(on('newyear',12,31)&&on('newyear',1,1)&&on('newyear',1,10)&&!on('newyear',1,11)&&!on('newyear',12,30));assert(on('christmas',12,25)&&on('thanksgiving',11,26)&&on('valentine',2,14)&&on('stpatrick',3,17)&&on('spring',4,1)&&on('july4',7,4)&&on('summer',8,1));let overlaps=0;for(let m=1;m<=12;m++)for(let d=1;d<=31;d++){const n=t.SEASON_ORDER.filter(id=>on(id,m,d)).length;if(n>1)overlaps++;}assert(!overlaps,'two seasons at once on '+overlaps+' days');});
check('Seasons: every seasonal game starts and plays, rewards are earned and kept, and the shop never sells them',()=>{t.setStrokes(stick());for(const id of t.SEASON_ORDER){store.set('gas-season-test',id);assert(t.seasonStart(id,0),'no start '+id);step(40);assert(t.game&&t.game.s.season&&t.game.s.season.id===id,'not seasonal '+id);t.backToDrawing();}store.set('gas-season-test','halloween');const SE=t.SEASONS.halloween;t.gpProg('season_halloween').stars={};const sh=t.shopState();sh.owned=sh.owned.filter(x=>x!=='hat:pumpkin'&&x!=='cape:bat');for(let i=0;i<4;i++)t.gpProg('season_halloween').stars['0-'+i]=2;let got=t.seasonRewards(SE);assert(got.length===1&&got[0].key==='pumpkin','half the levels should give the pumpkin head');for(let i=4;i<8;i++)t.gpProg('season_halloween').stars['0-'+i]=1;got=t.seasonRewards(SE);assert(got.length===1&&got[0].key==='bat','all levels should give the bat cape');assert(t.seasonRewards(SE).length===0,'rewards given twice');t.startModGame(t.SLING,{season:'halloween',level:0});const g=t.game;for(const b of g.s.mons)t.slKill(g,b);step(100);assert(g.over&&g.won&&/Level 1 done/.test(byId.get('resultTitle').textContent),byId.get('resultTitle').textContent);t.backToDrawing();t.openShop();const names=JSON.stringify(byId.get('modalBody').children.map(c=>(c.children||[]).map(x=>(x.children||[]).map(y=>y.textContent).join('|')).join('/')));assert(!/Pumpkin head|Santa hat/.test(names),'seasonal gear in the shop');t.closeModal();store.delete('gas-season-test');});
check('Seasons: theme, banner and calendar follow the date; out-of-season games stay locked; seasonal gear draws',()=>{store.set('gas-season-test','christmas');t.seasonApply();assert(t.seasonCur&&t.seasonCur.id==='christmas');assert(byId.get('seasonBox').children.length===2,'banner + calendar button');store.set('gas-season-test','valentine');t.seasonApply();assert(!t.seasonStart('christmas',0),'christmas should be locked in February');t.openSeasons();t.closeModal();store.delete('gas-season-test');t.setStrokes(stick());t.ensureRig();for(const it of t.SHOP_ITEMS.filter(i=>i.season)){const base=t.currentCharacter(),ch={...base,outfit:t.validOutfit({...base.outfit,[it.slot]:it.key}),morph:true,morphT:1};assert(ch.outfit[it.slot]===it.key,'invalid '+it.key);const c=doc.createElement('canvas');c.width=140;c.height=140;t.drawCharacterThumb(c,ch);}assert(t.perksFor({outfit:{weapon:'candycane'}}).melee==='candycane'&&t.perksFor({outfit:{weapon:'sparkler'}}).shoot==='wand');t.seasonApply();});
check('Note Rush: 15 songs, 3 rounds that get faster, tapping on time plays the song, missing costs hearts',()=>{assert(t.NR_SONGS.length===15);const c=t.nrChart(0,0,4);const rs=[0,1,2].map(r=>c.notes.filter(n=>n.r===r));assert(rs.every(x=>x.length>5),'3 rounds');assert(rs[2][1].t-rs[2][0].t<rs[0][1].t-rs[0][0].t,'round 3 should be faster');assert(c.notes.every(n=>n.lane>=0&&n.lane<4));assert(t.nrChart(0,0,5).notes.some(n=>n.lane===4),'guitar uses 5 lanes');t.setStrokes(stick());t.startModGame(t.NOTERUSH,{stage:0,level:0,inst:'piano'});let g=t.game,S=g.s;for(let f=0;f<60*90&&!g.over;f++){for(const n of S.notes)if(!n.hit&&!n.miss&&S.t>=n.t)t.nrHit(g,n.lane);step(1);}assert(g.won&&t.gpStars('notes',0,0)===3,'perfect play should 3-star');t.backToDrawing();t.startModGame(t.NOTERUSH,{stage:0,level:0});g=t.game;S=g.s;step(60*8);assert(S.hearts<5,'misses should cost hearts');const lane=S.notes.find(n=>!n.hit&&!n.miss&&n.t>S.t+1).lane,x=S.x0+lane*S.lw+S.lw/2;const before=S.hits;g.mod.pointer(g,'down',{x,y:600});assert(S.hits===before,'tapping early should not count');t.backToDrawing();t.openNotes();t.closeModal();});
check('scenes still fine after everything',()=>{for(let i=0;i<t.SCENES.length;i++){t.setBackground(i);step(1);}});
runChecks().then(()=>{console.log('\n'+passed+' passed, '+failed+' failed');if(failed){console.log('\n'+fails.join('\n\n'));process.exit(1);}process.exit(0);});
